// Источник: web-тест .qa/e2e/tests/journey/jr-01-real-data.spec.ts, план .qa/e2e/specs/journey.md (14.1), кейс .qa/tests/journey/JR-01-journey-overview-level-counters.md
// Тикет #6a86f7e8 (+#6a86f7e6, #6a86f7fb). Опора: «סולם דרגות התחזקות» AC1–AC3 (решение 06.09), «מוני תפילות» AC1/AC4, «מסך המסע האישי» AC1–AC5.
// Предусловие user1: 107 молитв (уровень 10), קבלה «test», в «מפת השפעה» 2 человека. Числа счётчиков сверяем с «בית», не с константами.
import { $$, driver, expect } from '@wdio/globals';
import { byText, byLabelStartsWith, byTextContains, tapText, expectVisibleText, scrollToText, swipeUp } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const COUNTERS = ['ימים רצופים', 'תפילות היום', 'סה״כ תפילות'];
const descAttr = () => (driver.isAndroid ? 'content-desc' : 'name');

/** Число из подписи доступности «<имя>: N» (region в web), с прокруткой до элемента. */
async function labelNumber(name: string, swipes = 6): Promise<number> {
  const el = await byLabelStartsWith(`${name}: `);
  for (let i = 0; i < swipes && !(await el.isDisplayed().catch(() => false)); i++) await swipeUp();
  await el.waitForDisplayed({ timeout: 20000 });
  const label = (await el.getAttribute(descAttr())) ?? '';
  const m = label.match(new RegExp(`^${name}: (\\d+)$`));
  if (!m) throw new Error(`Подпись «${label}» не в формате «${name}: N»`);
  return Number(m[1]);
}
/** Все элементы с подписью «…: הושג» / «…: טרם הושג». */
function achievementBadges() {
  return driver.isAndroid
    ? $$('android=new UiSelector().descriptionMatches(".+: (הושג|טרם הושג)")').getElements()
    : $$('-ios predicate string:name MATCHES ".+: (הושג|טרם הושג)"').getElements();
}
async function dismissMilestoneIfShown() {
  const w = await byTextContains('עלית דרגה');
  if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
}

describe('«המסע שלי»', () => {
  afterEach(async () => { await toHome(); });

  it('JR-01 «המסע שלי» на реальных данных — уровень, счётчики = главная, פילוח, последние молитвы, מפת השפעה, достижения #6a86f7e8 @prod-safe', async () => {
    // 1. «בית»: запомнить 3 счётчика.
    await goTab('בית');
    const home: Record<string, number> = {};
    for (const c of COUNTERS) home[c] = await labelNumber(c);

    // 2. «המסע שלי»: уровень 10 из 10.
    await goTab('המסע שלי');
    await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
    await dismissMilestoneIfShown();
    await expectVisibleText('מסור');
    await expectVisibleText('זו הדרגה הגבוהה ביותר');
    await expectVisibleText('דרגה 10 מתוך 10');

    // Счётчики = главная.
    for (const c of COUNTERS) expect(await labelNumber(c)).toBe(home[c]);
    await expect(byLabelStartsWith('מקבל על עצמי')).toBeExisting();

    // «פילוח תפילות»: שחרית + מנחה + ערבית = «סה״כ תפילות».
    await scrollToText('פילוח תפילות');
    let sum = 0;
    for (const p of ['שחרית', 'מנחה', 'ערבית']) sum += await labelNumber(p);
    expect(sum).toBe(home['סה״כ תפילות']);

    // «מפת השפעה»: «2 אנשים» + «הזמנת אדם להתחזק».
    await scrollToText('מפת השפעה');
    await scrollToText('2 אנשים');
    await scrollToText('הזמנת אדם להתחזק');

    // «הישגים» — 6 штук, каждое название один раз.
    await scrollToText('הישגים');
    await scrollToText('חודש רצוף');
    expect((await achievementBadges()).length).toBe(6);
    for (const n of ['תפילה ראשונה', 'שבוע שלם', 'חודש רצוף']) {
      const found = driver.isAndroid
        ? await $$(`android=new UiSelector().descriptionStartsWith("${n}: ")`).getElements()
        : await $$(`-ios predicate string:name BEGINSWITH "${n}: "`).getElements();
      expect(found.length).toBe(1);
    }

    // 3. «תפילות אחרונות» → «צפה בהכל» → экран истории (вместо URL /journey/history — экран «המסע שלי» сменился).
    await scrollToText('תפילות אחרונות');
    await (await scrollToText('צפה בהכל')).click();
    await expect(byText('תפילות אחרונות')).not.toBeDisplayed();
    await expect(byText('מפת השפעה')).not.toBeDisplayed();
  });
});
